using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Discriminator property renamed from "Discriminator" to "$type" in 9.0.
        // Preserve old name so existing documents are still queryable.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Fix 2: id format changed from "Blog|1" to "1" in 9.0.
        // Keep discriminator in id so existing documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminatorInJsonId();

        // Fix 3: Key property is now mapped directly to JSON "id" (shadow id removed).
        // Restore old shadow-id behavior so the key is still stored as a separate property.
        modelBuilder.Entity<Blog>().HasShadowId();

        // Fix 4: HasIndex now throws — removed the old HasIndex(b => b.Name) call.
        // Cosmos DB indexes all properties by default; configure custom policy in the portal.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

